Importance of Tree Data Structure:Trees are useful for storing data that naturally forms a hierarchy.File systems on computers are structured as trees, with folders containing subfolders and files.The DOM (Document Object Model) of an HTML page is a tree:The <html> tag is the root.<head> and <body> are its children.These tags can have their own child nodes, forming a hierarchical structure.Trees help in efficient data organization and retrieval for hierarchical relationships.Types of Tree Data Structures :Tree data structures can be classified based on the number of children each node can have.Binary Tree:Each node can have a maximum of two children.Full Binary Tree – every node has either 0 or 2 children.Complete Binary Tree – all levels are fully filled except possibly the last, which is filled from left to right.Balanced Binary Tree – height difference between left and right subtrees of every node is minimal.Ternary Tree:Each node can have at most three children, often labeled as left, middle, and right.N-ary Tree (or Generic Tree):Each node can have any number of children.Each node typically contains: Some data , A list of references to its children (duplicates are not allowed).Unlike linked lists, nodes store references to multiple child nodes.Please refer Types of Trees in Data Structures for details.Basic Operations Of Tree Data Structure:Create – create a tree in the data structure.Insert − Inserts data in a tree.Search − Searches specific data in a tree to check whether it is present or not.Traversal:Depth-First-Search TraversalBreadth-First-Search Traversal
            C++

    #include <iostream>
#include <vector>
using namespace std;

// Node structure for tree
class Node {
public:
    int data;
    vector<Node*> children;

    Node(int x) {
        data = x;
    }
};

// Function to add a child to a node
void addChild(Node* parent, Node* child) {
    parent->children.push_back(child);
}

// Function to print parents of each node
void printParents(Node* node, Node* parent) {
    if (parent == nullptr)
        cout << node->data << " -> NULL" << endl;
    else
        cout << node->data << " -> " << parent->data << endl;

    for (auto child : node->children)
        printParents(child, node);
}

// Function to print children of each node
void printChildren(Node* node) {
    cout << node->data << " -> ";
    for (auto child : node->children)
        cout << child->data << " ";
    cout << endl;

    for (auto child : node->children)
        printChildren(child);
}

// Function to print leaf nodes
void printLeafNodes(Node* node) {
    if (node->children.empty()) {
        cout << node->data << " ";
        return;
    }
    for (auto child : node->children)
        printLeafNodes(child);
}

// Function to print degrees of each node 
void printDegrees(Node* node, Node* parent) {
    int degree = node->children.size();
    if (parent != nullptr)  
        degree++;
    cout << node->data << " -> " << degree << endl;

    for (auto child : node->children)
        printDegrees(child, node);
}

int main() {
    // Creating nodes
    Node* root = new Node(1);
    Node* n2 = new Node(2);
    Node* n3 = new Node(3);
    Node* n4 = new Node(4);
    Node* n5 = new Node(5);

    // Constructing tree
    addChild(root, n2);
    addChild(root, n3);
    addChild(n2, n4);
    addChild(n2, n5);

    cout << "Parents of each node:" << endl;
    printParents(root, nullptr);

    cout << "Children of each node:" << endl;
    printChildren(root);

    cout << "Leaf nodes: ";
    printLeafNodes(root);
    cout << endl;

    cout << "Degrees of nodes:" << endl;
    printDegrees(root, nullptr);

    return 0;
}


